def cartesian_product(a, b):
    for i in a:
        for j in b:
            yield (i, j)


def cartesian_product_of_shape(dimentions, result=None):
    if result is None:
        result = [[]]

    for dim in dimentions:
        new_result = []
        for item in result:
            for i in range(dim):
                new_result.append(item + [i])
        result = new_result

    return result


def get_numpy_ndarray_rows(obj, shape=None):
    if shape is None:
        shape = obj.shape

    if len(shape) == 1:
        for i in range(shape[0]):
            yield (i,), obj[i]
    else:
        for i in range(shape[0]):
            sub_obj = obj[i]
            for path, row in get_numpy_ndarray_rows(sub_obj, shape[1:]):
                yield (i,) + path, row
